import numpy as np
rng=np.random.default_rng(42)
for n in (4,5,6):
 x=np.linspace(-1,1,n)
 c=np.array([1/np.prod(x[i]-np.delete(x,i)) for i in range(n)])
 w=rng.dirichlet(np.ones(n),size=100)
 hist={}
 for k in range(20001):
  if k in (0,100,1000,10000,20000): hist[k]=w.copy()
  v=c*c/np.maximum(w,1e-300); mu=v@x/v.sum(axis=1)
  w=v*(x-mu[:,None])**2; w/=w.sum(axis=1)[:,None]
 print(n,[(j,np.max(np.linalg.norm(hist[j]-hist[2*j],axis=1))) for j in (10000,)], 'early', np.max(np.linalg.norm(hist[1000]-hist[10000],axis=1)))
 print(hist[20000][np.argmax(np.linalg.norm(hist[10000]-hist[20000],axis=1))])
